def exportar_quadro_aderencia(df_quadro, nome_arquivo):
    """Exporta quadros documentais quando as pastas do pipeline já estiverem configuradas."""
    try:
        destino = DIR_QUADROS / nome_arquivo
        df_quadro.to_csv(destino, index=False, encoding="utf-8-sig")
        return str(destino)
    except Exception as exc:
        return f"Exportação não realizada nesta execução: {type(exc).__name__}: {exc}"

