# Controle global de exibição.
# Quando True, todo DataFrame salvo como tabela ou quadro também é renderizado
# no notebook com display(df), garantindo conferência visual em pandas.
IMPRIMIR_DATAFRAMES_NO_NOTEBOOK = True

def exibir_dataframe_pandas(numero, titulo, df, prefixo):
    """Renderiza qualquer tabela/quadro como pandas.DataFrame no notebook."""
    if not IMPRIMIR_DATAFRAMES_NO_NOTEBOOK:
        return
    try:
        display(Markdown(f"### {prefixo.capitalize()} {numero} — {titulo}"))
        display(df)
    except Exception:
        # Fallback para execução fora do Jupyter/IPython.
        print(f"\n{prefixo.capitalize()} {numero} — {titulo}")
        print(df.to_string(index=False))

def salvar_df(df, pasta, numero, titulo, prefixo):
    # Garante que o objeto exibido/salvo seja sempre um pandas.DataFrame.
    if not isinstance(df, pd.DataFrame):
        df = pd.DataFrame(df)

    nome = f"{prefixo}_{numero:02d}_" + (
        titulo.lower()
        .replace("ç", "c").replace("ã", "a").replace("á", "a")
        .replace("é", "e").replace("í", "i").replace("ó", "o")
        .replace("ú", "u").replace("â", "a").replace("ê", "e")
        .replace("/", "_").replace(" ", "_")
    )
    nome = "".join(ch for ch in nome if ch.isalnum() or ch in "._-")
    caminho = pasta / f"{nome[:150]}.csv"

    exibir_dataframe_pandas(numero, titulo, df, prefixo)
    df.to_csv(caminho, index=False, encoding="utf-8-sig")
    return caminho


