arquivo_excel = DIR_OUTPUTS / "resultados_tcc_pipeline_completo.xlsx"

def ler_csv_mais_recente_por_prefixo(pasta, prefixo):
    arquivos = sorted(pasta.glob(f"{prefixo}*.csv"), key=lambda p: p.stat().st_mtime, reverse=True)
    if not arquivos:
        return None, None
    return arquivos[0], pd.read_csv(arquivos[0], encoding="utf-8-sig")

with pd.ExcelWriter(arquivo_excel, engine="openpyxl") as writer:
    manifesto_df.to_excel(writer, sheet_name="manifesto", index=False)
    resumo_manifesto.to_excel(writer, sheet_name="resumo_manifesto", index=False)

    for numero, titulo in TABELAS:
        caminho_csv, df_tabela = ler_csv_mais_recente_por_prefixo(DIR_TABELAS, f"tabela_{numero:02d}_")
        if df_tabela is not None:
            sheet = f"tabela_{numero:02d}"
            df_tabela.to_excel(writer, sheet_name=sheet, index=False)

print("Excel consolidado salvo em:", arquivo_excel)


