def construir_sintese_desenvolvimento():
    partes = []
    partes.append("O notebook implementa um pipeline retrospectivo de Health Analytics aplicado à Natality Data 2024.")
    partes.append("A análise conecta seleção de variáveis, engenharia de atributos, proxy operacional RPM/PPROM, EDA, regressão logística e modelagem supervisionada.")
    partes.append("A proxy operacional é usada apenas como aproximação analítica compatível com contexto de RPM/PPROM, sem equivalência diagnóstica individual.")
    partes.append("A comparação entre cenário completo/perinatal e restritivo documenta o risco de vazamento temporal e impede leitura indevida do desempenho como prontidão clínica prospectiva.")
    partes.append("A avaliação combina discriminação, classificação, calibração, limiares decisórios, análise por decis e importância das variáveis.")
    partes.append("A entrega final é sustentada por manifesto, checklist de reprodutibilidade, tabelas, gráficos, quadros e exportação consolidada dos resultados.")
    return "\n".join(f"- {p}" for p in partes)

sintese_desenvolvimento_metodologico = construir_sintese_desenvolvimento()

try:
    with open(DIR_MANIFESTO / "sintese_desenvolvimento_metodologico.md", "w", encoding="utf-8") as f:
        f.write("# Síntese do desenvolvimento metodológico\n\n")
        f.write(sintese_desenvolvimento_metodologico)
except Exception as exc:
    print("Aviso: síntese não exportada neste momento:", exc)

display(Markdown("### Síntese do desenvolvimento metodológico"))
display(Markdown(sintese_desenvolvimento_metodologico))


